import csv
import os
from collections import Counter

# Constants
CSV_FILE_PATH = 'match_data.csv'

def create_test_csv(filename, content):
    """
    Utility function to create a CSV file for testing purposes.
    :param filename: Name of the CSV file to create.
    :param content: List of rows, where each row is a list of cell values.
    """
    with open(filename, 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerows(content)

def task_func(csv_file_path=CSV_FILE_PATH, goals_dict=None, penalties_dict=None):
    """
    Reads a CSV file and counts the total number of goals and penalties.
    Missing or malformed 'goals' and 'penalties' fields are treated as zero.
    Additionally, the function accepts two dictionaries, `goals_dict` and
    `penalties_dict`, where keys are team names and values are integers
    representing the number of goals or penalties. These values are added
    to the respective totals in the Counter.

    The function returns a Counter with keys 'goals' and 'penalties'.
    If the CSV file does not exist or is empty, the Counter is initialized
    with zero counts for both keys.

    :param csv_file_path: Path to the CSV file.
    :param goals_dict: Dictionary of team -> goals (int).
    :param penalties_dict: Dictionary of team -> penalties (int).
    :return: Counter({'goals': int, 'penalties': int})
    """
    # Ensure the dictionaries are not None
    goals_dict = goals_dict or {}
    penalties_dict = penalties_dict or {}

    # Initialize counts with zero for both keys
    counts = Counter({'goals': 0, 'penalties': 0})

    # If the file does not exist, return the zeroed Counter
    if not os.path.isfile(csv_file_path):
        # Add totals from the provided dictionaries
        for val in goals_dict.values():
            try:
                counts['goals'] += int(val)
            except (TypeError, ValueError):
                pass
        for val in penalties_dict.values():
            try:
                counts['penalties'] += int(val)
            except (TypeError, ValueError):
                pass
        return counts

    with open(csv_file_path, newline='') as csvfile:
        # Use DictReader to access columns by name
        reader = csv.DictReader(csvfile)

        # If the file has no rows or no header, return the zeroed Counter
        if reader.fieldnames is None:
            # Add totals from the provided dictionaries
            for val in goals_dict.values():
                try:
                    counts['goals'] += int(val)
                except (TypeError, ValueError):
                    pass
            for val in penalties_dict.values():
                try:
                    counts['penalties'] += int(val)
                except (TypeError, ValueError):
                    pass
            return counts

        for row in reader:
            # Safe dictionary access with default 0
            goals_raw = row.get('goals', 0)
            penalties_raw = row.get('penalties', 0)

            # Convert to integer, treating malformed values as zero
            try:
                goals_val = int(goals_raw)
            except (TypeError, ValueError):
                goals_val = 0

            try:
                penalties_val = int(penalties_raw)
            except (TypeError, ValueError):
                penalties_val = 0

            counts['goals'] += goals_val
            counts['penalties'] += penalties_val

    # Add totals from the provided dictionaries
    for val in goals_dict.values():
        try:
            counts['goals'] += int(val)
        except (TypeError, ValueError):
            pass
    for val in penalties_dict.values():
        try:
            counts['penalties'] += int(val)
        except (TypeError, ValueError):
            pass

    return counts

