from flask import Flask, render_template, redirect, url_for
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired
from flask_login import (
    LoginManager,
    UserMixin,
    login_user,
    login_required,
    logout_user,
    current_user,
)
from werkzeug.security import generate_password_hash, check_password_hash


def create_app(secret_key: str, template_folder: str) -> Flask:
    """
    Create and configure a Flask application.

    Parameters
    ----------
    secret_key : str
        Secret key used for session signing.
    template_folder : str
        Path to the folder containing Jinja2 templates.

    Returns
    -------
    Flask
        The configured Flask application instance.
    """
    app = Flask(__name__, template_folder=template_folder)
    app.secret_key = secret_key

    # ---------- Flask‑Login ----------
    login_manager = LoginManager()
    login_manager.init_app(app)
    login_manager.login_view = "login"

    # ---------- User model ----------
    class User(UserMixin):
        def __init__(self, id_: int, username: str, password_hash: str):
            self.id = id_
            self.username = username
            self.password_hash = password_hash

        def check_password(self, password: str) -> bool:
            return check_password_hash(self.password_hash, password)

    # In‑memory user store
    users = {}
    demo_user = User(
        id_=1,
        username="alice",
        password_hash=generate_password_hash("secret"),
    )
    users[demo_user.id] = demo_user

    @login_manager.user_loader
    def load_user(user_id: str):
        return users.get(int(user_id))

    # ---------- WTForms ----------
    class LoginForm(FlaskForm):
        username = StringField("Username", validators=[DataRequired()])
        password = PasswordField("Password", validators=[DataRequired()])
        submit = SubmitField("Login")

    # ---------- Routes ----------
    @app.route("/login", methods=["GET", "POST"])
    def login():
        form = LoginForm()
        if form.validate_on_submit():
            # Find user by username
            user = next(
                (u for u in users.values() if u.username == form.username.data), None
            )
            if user and user.check_password(form.password.data):
                login_user(user)
                return redirect(url_for("protected"))
            else:
                return "Invalid credentials", 401
        # Render a simple login form using a template string
        return render_template(
            "login.html",
            form=form,
        )

    @app.route("/logout")
    @login_required
    def logout():
        logout_user()
        return redirect(url_for("login"))

    @app.route("/protected")
    @login_required
    def protected():
        return f"Logged in as: {current_user.username}"

    return app


# ------------------------------------------------------------------
# If this module is executed directly, start the development server.
# ------------------------------------------------------------------
if __name__ == "__main__":
    # Example usage: create an app with a dynamic secret key and template folder.
    # The 'templates' folder should contain a 'login.html' template.
    app = create_app(secret_key="super-secret-key", template_folder="templates")
    app.run(debug=True)

