import cgi
import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}

def task_func():
    """
    Starts a simple HTTP server that handles POST requests containing JSON data.
    If the JSON payload contains a 'data' key, the server responds with a 200
    success message. Otherwise, it responds with a 400 error.
    """
    class SimplePostHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            # Read the request body
            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length)

            # Attempt to parse JSON; ignore errors as per instructions
            try:
                payload = json.loads(body)
            except Exception:
                payload = {}

            # Check for 'data' key and respond accordingly
            if 'data' in payload:
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode('utf-8'))
            else:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                error_resp = {
                    'status': 'error',
                    'message': 'Missing "data" key in JSON payload.'
                }
                self.wfile.write(json.dumps(error_resp).encode('utf-8'))

        # Suppress logging to keep output clean
        def log_message(self, format, *args):
            return

    # Set up and start the HTTP server
    server_address = ('', 8000)  # Listen on all interfaces, port 8000
    httpd = http.server.HTTPServer(server_address, SimplePostHandler)
    print('HTTP server running on port 8000. Press Ctrl+C to stop.')
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print('\nShutting down server.')
        httpd.server_close()

